from __future__ import annotations

from pathlib import Path


def replace_once(text: str, old: str, new: str, *, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected exactly one marker, got {count}")
    return text.replace(old, new)


roundtrip_path = Path("tests/test_transport_roundtrip.py")
roundtrip = roundtrip_path.read_text(encoding="utf-8")

helper_marker = "\n\nclass TransportRoundtripTests(unittest.TestCase):\n"
helper = '''\n\ndef _consume_shared_worker(\n    state_root: str,\n    start: multiprocessing.synchronize.Event,\n    output: multiprocessing.queues.Queue,\n) -> None:\n    root = Path(state_root)\n    roundtrip.STATE_ROOT = root\n    roundtrip.LOCK_PATH = root / ".lock"\n    start.wait()\n    try:\n        receipt = roundtrip.consume_verified(\n            client_scope=SHARED_SCOPE,\n            runtime_binding=BINDING,\n            tool_name="grabowski_file_write",\n            arguments_sha256="e" * 64,\n            now_unix=102,\n        )\n    except Exception as exc:\n        output.put(("error", type(exc).__name__))\n    else:\n        output.put(("ok", receipt["consumption_receipt_sha256"]))\n\n\nclass TransportRoundtripTests(unittest.TestCase):\n'''
roundtrip = replace_once(roundtrip, helper_marker, helper, label="shared consumer helper")

methods_marker = "    def test_different_client_scope_cannot_ack_or_consume(self) -> None:\n"
methods = '''    def test_shared_unlabeled_handshakes_coexist_without_overwrite(self) -> None:\n        first = self.begin(scope=SHARED_SCOPE)\n        second = self.begin(scope=SHARED_SCOPE)\n        self.assertFalse(first["replayed"])\n        self.assertFalse(second["replayed"])\n        self.assertNotEqual(\n            first["challenge_receipt_sha256"],\n            second["challenge_receipt_sha256"],\n        )\n        self.assertEqual(second["pending_challenge_count"], 2)\n\n        second_ack = self.acknowledge(\n            second["challenge_receipt_sha256"],\n            scope=SHARED_SCOPE,\n        )\n        first_ack = self.acknowledge(\n            first["challenge_receipt_sha256"],\n            scope=SHARED_SCOPE,\n        )\n        self.assertNotEqual(\n            first_ack["verification_receipt_sha256"],\n            second_ack["verification_receipt_sha256"],\n        )\n        self.assertEqual(first_ack["verified_receipt_count"], 2)\n\n        first_consumption = roundtrip.consume_verified(\n            client_scope=SHARED_SCOPE,\n            runtime_binding=BINDING,\n            tool_name="first-write",\n            arguments_sha256="d" * 64,\n            now_unix=102,\n        )\n        second_consumption = roundtrip.consume_verified(\n            client_scope=SHARED_SCOPE,\n            runtime_binding=BINDING,\n            tool_name="second-write",\n            arguments_sha256="e" * 64,\n            now_unix=102,\n        )\n        self.assertNotEqual(\n            first_consumption["verification_receipt_sha256"],\n            second_consumption["verification_receipt_sha256"],\n        )\n        self.assertEqual(second_consumption["verified_receipt_count"], 0)\n        status = roundtrip.status(\n            client_scope=SHARED_SCOPE,\n            runtime_binding=BINDING,\n            now_unix=103,\n        )\n        self.assertEqual(status["state"], "consumed")\n        self.assertFalse(status["mutation_gate_open"])\n\n    def test_shared_unlabeled_parallel_consumers_use_distinct_tokens(self) -> None:\n        for _ in range(2):\n            begin = self.begin(scope=SHARED_SCOPE)\n            self.acknowledge(\n                begin["challenge_receipt_sha256"],\n                scope=SHARED_SCOPE,\n            )\n        context = multiprocessing.get_context("fork")\n        start = context.Event()\n        output = context.Queue()\n        processes = [\n            context.Process(\n                target=_consume_shared_worker,\n                args=(str(roundtrip.STATE_ROOT), start, output),\n            )\n            for _ in range(2)\n        ]\n        for process in processes:\n            process.start()\n        start.set()\n        for process in processes:\n            process.join(timeout=10)\n            self.assertFalse(process.is_alive())\n            self.assertEqual(process.exitcode, 0)\n        results = [output.get(timeout=2) for _ in processes]\n        self.assertEqual(sorted(result[0] for result in results), ["ok", "ok"])\n        self.assertEqual(len({result[1] for result in results}), 2)\n\n    def test_shared_pending_pool_is_bounded_and_prunes_stale_entries(self) -> None:\n        with mock.patch.object(roundtrip, "MAX_SHARED_PENDING_CHALLENGES", 2):\n            self.begin(scope=SHARED_SCOPE, now=100)\n            self.begin(scope=SHARED_SCOPE, now=100)\n            with self.assertRaisesRegex(\n                roundtrip.TransportRoundtripRequired,\n                "pending challenge pool is full",\n            ):\n                self.begin(scope=SHARED_SCOPE, now=100)\n            refreshed = self.begin(\n                scope=SHARED_SCOPE,\n                now=100 + roundtrip.CHALLENGE_TTL_SECONDS + 1,\n            )\n        self.assertEqual(refreshed["pending_challenge_count"], 1)\n\n    def test_shared_verified_pool_is_bounded_and_preserves_pending_challenge(self) -> None:\n        with mock.patch.object(roundtrip, "MAX_SHARED_VERIFIED_RECEIPTS", 1):\n            first = self.begin(scope=SHARED_SCOPE, now=100)\n            second = self.begin(scope=SHARED_SCOPE, now=100)\n            self.acknowledge(\n                first["challenge_receipt_sha256"],\n                scope=SHARED_SCOPE,\n                now=101,\n            )\n            with self.assertRaisesRegex(\n                roundtrip.TransportRoundtripRequired,\n                "verified receipt pool is full",\n            ):\n                self.acknowledge(\n                    second["challenge_receipt_sha256"],\n                    scope=SHARED_SCOPE,\n                    now=101,\n                )\n            status = roundtrip.status(\n                client_scope=SHARED_SCOPE,\n                runtime_binding=BINDING,\n                now_unix=102,\n            )\n        self.assertEqual(status["pending_challenge_count"], 1)\n        self.assertEqual(status["verified_receipt_count"], 1)\n\n    def test_legacy_single_slot_state_migrates_on_next_mutation(self) -> None:\n        begin = self.begin()\n        path = roundtrip._state_path(roundtrip.client_scope_sha256(META_SCOPE))\n        current = json.loads(path.read_text(encoding="utf-8"))\n        legacy = {\n            "schema_version": roundtrip.SCHEMA_VERSION,\n            "kind": roundtrip.STATE_KIND,\n            "client_scope_sha256": current["client_scope_sha256"],\n            "client_scope_kind": current["client_scope_kind"],\n            "pending_challenge": current["pending_challenges"][0],\n            "verified_receipt": None,\n            "last_consumption_receipt": None,\n        }\n        roundtrip._write_private_json(path, legacy)\n        acknowledged = self.acknowledge(begin["challenge_receipt_sha256"])\n        migrated = json.loads(path.read_text(encoding="utf-8"))\n        self.assertEqual(migrated["schema_version"], roundtrip.STATE_SCHEMA_VERSION)\n        self.assertEqual(len(migrated["verified_receipts"]), 1)\n        self.assertEqual(acknowledged["state"], "verified")\n\n    def test_different_client_scope_cannot_ack_or_consume(self) -> None:\n'''
roundtrip = replace_once(roundtrip, methods_marker, methods, label="shared pool test methods")
roundtrip = replace_once(
    roundtrip,
    'payload["pending_challenge"]["runtime_binding"]["release_id"] = "tampered"',
    'payload["pending_challenges"][0]["runtime_binding"]["release_id"] = "tampered"',
    label="state schema tamper assertion",
)
roundtrip_path.write_text(roundtrip, encoding="utf-8")

integration_path = Path("tests/test_transport_gate_integration.py")
integration = integration_path.read_text(encoding="utf-8")
integration_marker = "    def test_handshake_grip_is_narrowly_exempt(self) -> None:\n"
integration_method = '''    def test_stateless_shared_scope_admits_two_independent_handshakes(self) -> None:\n        temporary = tempfile.TemporaryDirectory()\n        self.addCleanup(temporary.cleanup)\n        root = Path(temporary.name) / "state"\n        with mock.patch.object(\n            roundtrip, "STATE_ROOT", root\n        ), mock.patch.object(\n            roundtrip, "LOCK_PATH", root / ".lock"\n        ):\n            challenges = [\n                roundtrip.begin(\n                    client_scope=SHARED_SCOPE,\n                    runtime_binding=BINDING,\n                    now_unix=100,\n                )["challenge_receipt_sha256"]\n                for _ in range(2)\n            ]\n            for challenge in challenges:\n                roundtrip.acknowledge(\n                    client_scope=SHARED_SCOPE,\n                    challenge_receipt_sha256=challenge,\n                    runtime_binding=BINDING,\n                    now_unix=101,\n                )\n\n            operator = self.configured_operator()\n            context = types.SimpleNamespace(client_id=None)\n            first = asyncio.run(\n                operator.mcp._tool_manager.call_tool(\n                    "write", {"sequence": 1}, context\n                )\n            )\n            second = asyncio.run(\n                operator.mcp._tool_manager.call_tool(\n                    "write", {"sequence": 2}, context\n                )\n            )\n            self.assertTrue(first["called"])\n            self.assertTrue(second["called"])\n            with self.assertRaisesRegex(\n                RuntimeError, "fresh single-use transport verification"\n            ):\n                asyncio.run(\n                    operator.mcp._tool_manager.call_tool(\n                        "write", {"sequence": 3}, context\n                    )\n                )\n\n    def test_handshake_grip_is_narrowly_exempt(self) -> None:\n'''
integration = replace_once(
    integration,
    integration_marker,
    integration_method,
    label="central gate shared-pool integration test",
)
integration_path.write_text(integration, encoding="utf-8")
